mapper.select:
SELECT ATT_SO.SUBSIDIARY_CODE ,ATT_SO.EMPLOYEE_NO ,EM.FULL_NAME_LOCAL AS employee_Name ,EM.ORG_NAME_LOCAL AS organization_Name ,EM.organization_ID AS organization_ID ,ATT_SO.SHIFT_TYPE_CODE AS SHIFT_TYPE_CODE ,(SELECT lgvhr_common_pkg.decode_lookup('LGVHR_SHIFT_TYPE_CODE', ATT_SO.SHIFT_TYPE_CODE, NULL, 'en') AS FROM dual) AS SHIFT_TYPE_NAME ,ATT_SO.TIME_AND_ATTENDANCE_YYYYMM ,ATT_SO.OT_LEVEL ,ATT_SO.OT_TOTAL ,ATT_SO.LOWER_LIMIT ,ATT_SO.UPPER_LIMIT ,ATT_SO.TIME_ATTEND_INPUT_REASON_DESC ,ATT_SO.CREATION_USER_ID ,ATT_SO.CREATION_DATE ,ATT_SO.LAST_UPDATE_USER_ID ,ATT_SO.LAST_UPDATE_DATE FROM TB_ATT_OT_LEVEL_REQUEST_N ATT_SO LEFT OUTER JOIN EMP_MASTER EM ON (ATT_SO.EMPLOYEE_NO = EM.EMPLOYEE_NUMBER) WHERE 1=1 AND ATT_SO.SUBSIDIARY_CODE = #{subsidiaryCode}
AND ATT_SO.REQUEST_NO = #{requestNo}
AND ATT_SO.approval_request_id = #{requestMasterId} ORDER BY ATT_SO.REQUEST_SEQ_NO ASC

select /* LGVATT20030.retrieveOtLevelInfo */ em.attribute10 as shift_type_code ,lgvatt_ot_calculation_pkg.get_ot_total(em.subsidiary_code, em.employee_number, TO_DATE(#{timeAndAttendanceYyyymm}, 'YYYYMM'),TO_DATE(#{timeAndAttendanceYyyymm}, 'YYYYMM'), 'month_total_ot_yyyymm') as ot_total ,lgvatt_ot_level_pkg.get_ot_level(em.subsidiary_code, em.employee_number, #{timeAndAttendanceYyyymm}, 'request_next_ot_level') as ot_level ,lgvatt_ot_level_pkg.get_ot_level(em.subsidiary_code, em.employee_number, #{timeAndAttendanceYyyymm}, 'request_lower_limit') as lower_limit ,lgvatt_ot_level_pkg.get_ot_level(em.subsidiary_code, em.employee_number, #{timeAndAttendanceYyyymm}, 'request_upper_limit') as upper_limit from emp_master em where em.subsidiary_code = 'LGDVN' AND em.employee_number = #{employeeNo}
AND lgvatt_ot_level_pkg.get_ot_level(em.subsidiary_code, em.employee_number, #{timeAndAttendanceYyyymm}, 'request_next_ot_level') = #{otLevel}
AND em.ORGANIZATION_ID = #{organizationId}

mapper.update:
	 MERGE /* LGVATT20030.saveOtLevelRequest */ INTO TB_ATT_OT_LEVEL_REQUEST_N ATT_SO
     USING DUAL
             ON (     
                  	  ATT_SO.REQUEST_CODE = #{requestCode}
                  AND ATT_SO.APPROVAL_REQUEST_ID = #{approvalRequestId}
                  AND ATT_SO.EMPLOYEE_NO = #{employeeNo}
                  AND ATT_SO.TIME_AND_ATTENDANCE_YYYYMM = #{timeAndAttendanceYyyymm}
                )
       WHEN MATCHED THEN
            UPDATE SET                         
                     ATT_SO.OT_LEVEL               = #{otLevel}
                    ,ATT_SO.OT_TOTAL               = #{otTotal}
                    ,ATT_SO.SHIFT_TYPE_CODE        = #{shiftTypeCode}
                    ,ATT_SO.LOWER_LIMIT            = #{lowerLimit}
                    ,ATT_SO.UPPER_LIMIT            = #{upperLimit}
                    ,CONFIRM_FLAG                  = 'Y'
                    ,PROGRESS_STATUS_CODE          = (SELECT status_code FROM lgcom_approval_request_n WHERE request_master_id = ATT_SO.approval_request_id AND request_code = ATT_SO.request_code) 
                    ,LAST_UPDATE_USER_ID                   = #{sessionUserId}
                    ,LAST_UPDATE_DATE                      = SYSDATE
       WHEN NOT MATCHED THEN
            INSERT 
                   ( 
                    REQUEST_NO
                   ,REQUEST_SEQ_NO 
                   ,REQUEST_DATE
                   ,SUBSIDIARY_CODE
                   ,EMPLOYEE_NO
                   ,TIME_AND_ATTENDANCE_YYYYMM
                   ,OT_LEVEL
                   ,OT_TOTAL
                   ,SHIFT_TYPE_CODE
                   ,LOWER_LIMIT
                   ,UPPER_LIMIT
                   ,TIME_ATTEND_INPUT_REASON_DESC
                   ,APPROVAL_REQUEST_ID
                   ,REQUEST_CODE
                   ,PROGRESS_STATUS_CODE
                   ,CONFIRM_FLAG                   
                   ,CREATION_USER_ID
                   ,CREATION_DATE
                   ,LAST_UPDATE_USER_ID
                   ,LAST_UPDATE_DATE
                    )VALUES(
                    #{requestNo}
                   ,sq_tb_att_special_ot_id.NEXTVAL
                   ,SYSDATE
                   ,#{subsidiaryCode} 
                   ,#{employeeNo}
                   ,#{timeAndAttendanceYyyymm}
                   ,#{otLevel}
                   ,#{otTotal}
                   ,#{shiftTypeCode}
                   ,#{lowerLimit}
                   ,#{upperLimit}
                   ,#{timeAttendInputReasonDesc}
                   ,#{approvalRequestId}
                   ,#{requestCode}
                   ,'20'
                   ,'N'                     
                   ,#{sessionUserId}
                   ,SYSDATE
                   ,#{sessionUserId}
                   ,SYSDATE
                       )

	UPDATE TB_ATT_OT_LEVEL_REQUEST_N ATT_SO
	   SET ATT_SO.PROGRESS_STATUS_CODE		= (SELECT status_code FROM lgcom_approval_request_n WHERE request_master_id = ATT_SO.approval_request_id AND request_code = ATT_SO.request_code) 
          ,ATT_SO.LAST_UPDATE_USER_ID      = #{sessionUserId}
          ,ATT_SO.LAST_UPDATE_DATE         = SYSDATE
	 WHERE ATT_SO.SUBSIDIARY_CODE 			= #{LGVHR_PROJECT_SESSION.subsidiaryCode} 
	   AND ATT_SO.REQUEST_CODE 			= #{requestCode}
       AND ATT_SO.APPROVAL_REQUEST_ID 		= #{approvalRequestId}

DELETE FROM TB_ATT_OT_LEVEL_REQUEST_N ATT_SO
 WHERE ATT_SO.SUBSIDIARY_CODE = #{subsidiaryCode} 
   AND ATT_SO.TIME_AND_ATTENDANCE_DATE = TO_DATE(#{timeAndAttendanceDate}, 'DD/MM/YYYY') 
   AND ATT_SO.EMPLOYEE_NO = #{employeeNo}

mapper.select:
SELECT
EM.FULL_NAME_LOCAL AS requestor_info ,(SELECT common_code_name FROM LGCOM_COMMON_CODE_MULTI_LANG_C WHERE code_type_code = 'LGCOM_APPROVAL_REQ_STATUS_CODE' AND language_code = NVL('en','en') AND common_code = ATT_SO.PROGRESS_STATUS_CODE) AS status_name ,TO_CHAR(ATT_SO.LAST_UPDATE_DATE, 'DD/MM/YYYY') AS request_date , ATT_SO.PROGRESS_STATUS_CODE as startus_code
FROM TB_ATT_OT_LEVEL_REQUEST_N ATT_SO LEFT OUTER JOIN EMP_MASTER EM ON (ATT_SO.EMPLOYEE_NO = EM.EMPLOYEE_NUMBER) LEFT OUTER JOIN tb_att_result_n tar ON (tar.employee_no = ATT_SO.EMPLOYEE_NO AND TAR.time_and_attendance_date = ATT_SO.TIME_AND_ATTENDANCE_DATE) WHERE 1=1 AND ATT_SO.TIME_AND_ATTENDANCE_DATE = TO_DATE(#{timeAndAttendanceDate}, 'DD/MM/YYYY') AND ATT_SO.EMPLOYEE_NO = #{employeeNo} AND ATT_SO.SUBSIDIARY_CODE = #{subsidiaryCode} AND ATT_SO.LAST_UPDATE_USER_ID = #{sessionUserId}


    SELECT COUNT(*) AS dup_count
	FROM   TB_ATT_OT_LEVEL_REQUEST_N ta
	WHERE  1 = 1
	AND    ta.subsidiary_code = #{subsidiaryCode}
	AND    ta.time_and_attendance_yyyymm = #{timeAndAttendanceYyyymm}
	AND    ta.progress_status_code IN ('20', '30') --기등록 건( 50: Cancel 제외)
	AND    NVL(ta.confirm_flag, 'N') <> 'R'   -- Rejected
	AND    ta.employee_no = #{employeeNo}
